#!/usr/bin/env python3
from __future__ import annotations
import json
from pathlib import Path
from typing import Any

ROOT=Path(__file__).resolve().parents[1]
DB=ROOT/'data'/'project_msr_database.full.json'

def all_tasks(db:dict[str,Any])->list[dict[str,Any]]:
    return list(db.get('tasks') or [])+[t for module in (db.get('pathway_modules') or {}).values() for stage in module.values() for t in stage]

def impl_step(task:dict[str,Any], sid:str, action:str, location:str, inputs:list[str], guidance:str, tools:list[str], outputs:list[str], acceptance:str, hold:str='')->dict[str,Any]:
    return {
        'step_id':sid,
        'action':action,
        'responsible_role':task.get('responsible_role') or 'Assigned technical lead',
        'supporting_roles':(task.get('engineering_work_package') or {}).get('resource_plan',{}).get('core_producing_team') or [],
        'work_location':location,
        'required_inputs':inputs,
        'detailed_guidance':guidance,
        'tools_equipment':tools,
        'outputs_and_records':outputs,
        'acceptance_condition':acceptance,
        'hold_point':hold,
    }

def enrich_chem_test(test:dict[str,Any])->None:
    text=(test.get('campaign') or '').lower()
    generic=[
        'Approve the test objective, decision supported, configuration, material stage, measured quantities, uncertainty target, sample plan, and acceptance basis.',
        'Verify material identity/genealogy, equipment configuration, calibrations, cleanliness, atmospheric controls, hazards, and waste/disposition route before work begins.',
        'Execute a pre-test prediction or expected-response calculation and freeze the prediction before the measured result is released to the analysis team.',
        'Run the planned sequence with time-synchronized process data, operator log, configuration changes, sample custody, and exception records.',
        'Perform replicate or confirmatory measurements, calculate uncertainty and material balance, reconcile laboratory and online measurements, and document outliers.',
        'Independently review the qualified dataset, compare it to acceptance criteria and model predictions, disposition discrepancies, and release the data with conditions of use.',
    ]
    controlled=['salt composition and supplier lot','temperature history and thermal cycling','cover-gas composition/flow where applicable','contact material and exposed surface condition','sampling time/location and analytical method','equipment configuration and calibration status']
    equipment=['qualified salt preparation/transfer equipment','controlled-atmosphere enclosure or cover-gas system','calibrated temperature, mass, flow, pressure, and electrochemical instruments','qualified sample containers and chain-of-custody materials','approved analytical laboratory methods and reference standards','time-synchronized data-acquisition and records system']
    if any(k in text for k in ['purification','synthesis','feed qualification']):
        controlled += ['starting impurity vector','batch mass and mixing history','purification/synthesis route identifier','residual heel and recovery fraction']
        equipment += ['batch preparation vessel and transfer system','representative purification media/reagents selected by the approved process','independent analytical laboratory']
    if any(k in text for k in ['corrosion','weld','material']):
        controlled += ['alloy heat and weld/joining pedigree','surface finish and specimen geometry','flow/thermal-gradient exposure','pre/post exposure mass and dimensions']
        equipment += ['traceable coupons/weldments','metallography and microscopy tools','mechanical test and NDE capability']
    if any(k in text for k in ['off-gas','noble gas','aerosol','volatile','capture','plate-out','particulate']):
        controlled += ['surrogate species injection history','gas residence time and flow split','surface-area and temperature map','filter/sorbent identity and loading','deposition and recovery locations']
        equipment += ['gas injection and metering system','representative off-gas train','particle/aerosol and gas-species monitoring','removable deposition coupons and recoverable filters/sorbents']
    if any(k in text for k in ['rare-earth','fission-product','speciation']):
        controlled += ['surrogate species group and concentration ladder','redox condition','precipitation/solubility boundary','actinide-retention surrogate or authorized confirmatory measurement']
        equipment += ['surrogate dosing system','phase/speciation analysis capability','closed material-balance collection system']
    if any(k in text for k in ['sensor','sampling','monitor']):
        controlled += ['sensor serial number and calibration','immersion/exposure history','sampling probe geometry and purge history','drift/fouling challenge','laboratory cross-check timing']
        equipment += ['online sensor test rack','hot sampling assembly','reference-electrode or calibration system','laboratory cross-check equipment']
    if 'irradiated' in text or 'demonstrator' in text:
        generic[1]='Confirm the DOE/host authorization, radiological work package, material-control boundaries, hot-cell/sample-transfer route, dose/contamination controls, and approved waste/end-state disposition before the activity begins.'
        equipment += ['authorized hot-cell or shielded analytical capability','radiological survey and contamination-control equipment','MC&A-compatible sample and residue tracking']
    test['minimum_test_sequence']=generic
    test['controlled_variables']=list(dict.fromkeys(controlled))
    test['equipment_and_consumables']=list(dict.fromkeys(equipment))
    test['replicate_and_uncertainty_strategy']='Use at least duplicate independently analyzed samples for acceptance-critical chemistry, repeat the condition after configuration stabilization, include blanks/reference materials where applicable, and define the uncertainty budget before test execution. Any reduction in replication requires a documented technical basis and independent approval.'
    test['sample_and_archive_plan']='Assign a unique genealogy to feed, intermediate, product, deposits, filters/sorbents, residues, and retained reference samples. Record time/location/configuration, preserve sufficient archive material for dispute resolution and method reanalysis, and reconcile all samples to the campaign material balance.'
    test['stop_conditions']=['loss of required atmosphere, temperature, containment, or criticality/material-control boundary','instrument/calibration condition outside the approved range','uncontrolled composition change, leak, plugging, precipitation, or unexpected pressure/flow response','material balance discrepancy or sample-custody break that could invalidate the conclusion','result outside a safety, authorization, equipment-protection, or preapproved test-abort limit']
    test['data_products']=['controlled test procedure and readiness record','as-tested configuration and material genealogy','raw time-series and laboratory data in native format','calibration and uncertainty records','sample/deposit/filter inventory and material balance','qualified dataset and comparison to prediction','discrepancy dispositions and approved data-release memo']
    test['decision_rule']='Credit the result only when the approved configuration was maintained, measurement uncertainty supports the required discrimination, material/sample balance is reconciled, independent review is complete, and the result is within acceptance or has an approved model/design/process update and retest disposition.'


def set_task_plan(task:dict[str,Any], *, summary:str, steps:list[dict[str,Any]], playbooks:list[str], procurement:list[str], long_leads:list[dict[str,str]], decisions:list[dict[str,str]], field:list[dict[str,str]], contingencies:list[dict[str,str]], test_ids:list[str]|None=None, acceptance_matrix:list[dict[str,str]]|None=None)->None:
    plan=task['implementation_plan']
    plan['implementation_readiness']='Task-specific execution sequence, procurement/partner actions, facility work, decision gates, acceptance evidence, and fallback routes are defined for the current planning basis.'
    plan['implementation_summary']=summary
    plan['implementation_steps']=steps
    plan['linked_playbooks']=sorted(set(playbooks))
    plan['procurement_and_contracting_actions']=procurement
    plan['long_lead_items']=long_leads
    plan['decision_points']=decisions
    plan['field_lab_or_vendor_activities']=field
    plan['fallbacks_and_contingencies']=contingencies
    if test_ids is not None: plan['task_specific_test_ids']=test_ids
    if acceptance_matrix is not None: plan['task_specific_acceptance_matrix']=acceptance_matrix
    task['engineering_work_package']['implementation_summary']=summary


def main()->int:
    db=json.load(DB.open())
    tasks=all_tasks(db); by={t['id']:t for t in tasks}
    chem_tests=db['chemistry_processing_plan']['experiment_matrix']
    for test in chem_tests: enrich_chem_test(test)
    db['test_matrices']['fuel_salt_chemistry_and_processing']=chem_tests
    db['implementation_playbooks']['PB-CHEM-01']['experiment_matrix']=chem_tests

    # Fuel specification, source, synthesis, and delivery.
    t=by['S-INL-05']
